CREATE FUNCTION public.origem_login(p_ip_hash text, p_code_hash text, p_token_hash text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE n integer; c public.origem_companies%ROWTYPE; BEGIN PERFORM pg_advisory_xact_lock(hashtext(p_ip_hash)); SELECT count(*) INTO n FROM public.origem_attempts WHERE ip_hash=p_ip_hash AND NOT succeeded AND created_at>now()-interval '15 minutes'; IF n>=8 THEN RETURN NULL; END IF; SELECT * INTO c FROM public.origem_companies WHERE code_hash=p_code_hash AND blocked=false AND expires_at>now(); INSERT INTO public.origem_attempts(ip_hash,succeeded) VALUES(p_ip_hash,c.id IS NOT NULL); IF c.id IS NULL THEN INSERT INTO public.origem_audit(actor,action) VALUES('anonymous','login_failed'); RETURN NULL; END IF; INSERT INTO public.origem_sessions(company_id,token_hash,expires_at) VALUES(c.id,p_token_hash,LEAST(c.expires_at,now()+interval '7 days')); UPDATE public.origem_companies SET last_access_at=now() WHERE id=c.id; INSERT INTO public.origem_audit(actor,action,company_id) VALUES('client','login_success',c.id); RETURN jsonb_build_object('company',c.name,'expiresAt',c.expires_at); END $$;
REVOKE ALL ON FUNCTION public.origem_login(text,text,text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.origem_login(text,text,text) TO service_role;